// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address addr, address target, bool emergency) public {
        vm.assume(addr != address(0));
        // Configure the DAO to allow the test contract as a governed address
        address[] memory governables = new address[](1);
        governables[0] = addr;
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;

        // Since the test contract is the DAO, it can call setGoverned
        c.setGoverned(governables, isGoverned);

        // Now call assertGovernanceApproved as the governed address
        vm.prank(addr);
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", addr, target, emergency));

        // The general rule: the first address should be governed (true) after setGoverned
        // In the reference, this is true; in the mutant with i=1, it is false
        assertTrue(c.governed(addr) == true);
    }
}

